"use client";

import { create } from "zustand";
import { persist } from "zustand/middleware";

/* ─────────────────────────────────────────────
   TIPOS PÚBLICOS
───────────────────────────────────────────── */

export type ChatTurn = { role: "titan" | "user"; text: string };

export type Profile = {
  name?: string;
  age?: string;
  sex?: string;
  height?: string;
  weight?: string;
  targetWeight?: string;
  goal?: string;
  level?: string;
  trainingDays?: string;
  trainingPlace?: string;
  equipment?: string;
  injury?: string;
  allergies?: string;
  dietPreference?: string;
  sleepHours?: string;
  dailyActivity?: string;
  supermarket?: string;
};

export type LoggedSet = { weight: number; reps: number; rpe: number };

export type Exercise = {
  id: string;
  name: string;
  targetSets: number;
  targetReps: string;
  muscleGroup?: string;
  loggedSets: LoggedSet[];
};

export type MealMacros = {
  name: string;
  kcal: number;
  protein: number;
  carbs: number;
  fat: number;
};

export type Meal = MealMacros & {
  id: string;
  icon: string;
  alternatives: MealMacros[];
};

export type ShoppingItem = {
  id: string;
  name: string;
  category: string;
  checked: boolean;
  quantity?: string;
  fromMenu?: boolean; // auto-generated from weekly menu
};

export type WeighIn = { date: string; weight: number };

export type ChatMessage = { role: "user" | "titan"; text: string };

export type Achievement = {
  id: string;
  title: string;
  description: string;
  icon: string;
  unlockedAt?: string;
  xpReward: number;
};

export type ChallengeType = "daily" | "weekly" | "monthly";

export type Challenge = {
  id: string;
  title: string;
  description: string;
  type: ChallengeType;
  progress: number;
  target: number;
  unit: string;
  xpReward: number;
  completed: boolean;
  requiresWatch: boolean;
};

export type Friend = {
  id: string;
  name: string;
  level: number;
  xp: number;
  streak: number;
  avatar?: string;
  commitmentIndex: number;
  position: number;
  status: "accepted" | "pending_sent" | "pending_received";
};

export type FeedItem = {
  id: string;
  userId: string;
  userName: string;
  action: string;
  timestamp: string;
  icon: string;
};

export type Duel = {
  id: string;
  opponentId: string;
  opponentName: string;
  type: string;
  myScore: number;
  opponentScore: number;
  status: "active" | "won" | "lost" | "pending";
  startedAt: string;
  endsAt: string;
};

export type DailyStats = {
  date: string;
  water: number;       // litros
  steps: number;
  sleepHours: number;
  caloriesBurned: number;
  workoutMinutes: number;
  proteinGrams: number;
  screenMinutes: number;
  fromWatch: boolean;
};

export type HealthSource = "apple_health" | "health_connect" | "manual" | "none";

export type ProgressPhoto = {
  id: string;
  date: string;        // ISO date string
  dataUrl: string;     // base64 data URL stored locally
  note?: string;
};

// Historial de comidas por día (clave: "YYYY-MM-DD")
export type DayMeals = {
  date: string;
  meals: Meal[];
  completed: Record<string, boolean>;
};

export type NotificationSettings = {
  enabled: boolean;
  remindFood: boolean;
  remindWater: boolean;
  remindWorkout: boolean;
  dailySummary: boolean;
  weeklySummary: boolean;
  duelAvailable: boolean;
  friendSurpassed: boolean;
};

/* ─────────────────────────────────────────────
   FUNCIONES DE UTILIDAD (exportadas)
───────────────────────────────────────────── */

export function xpToLevel(xp: number): {
  level: number;
  levelXp: number;
  nextLevelXp: number;
} {
  let level = 1;
  let accumulated = 0;
  while (accumulated + 500 * level <= xp) {
    accumulated += 500 * level;
    level++;
  }
  return { level, levelXp: xp - accumulated, nextLevelXp: 500 * level };
}

export function commitmentIndex(stats: {
  workoutsThisWeek: number;
  nutritionDays: number;
  avgSteps: number;
  avgWater: number;
  avgSleep: number;
}): number {
  const workout = Math.min(stats.workoutsThisWeek / 4, 1) * 40;
  const nutrition = Math.min(stats.nutritionDays / 5, 1) * 25;
  const steps = Math.min(stats.avgSteps / 10000, 1) * 15;
  const water = Math.min(stats.avgWater / 2, 1) * 10;
  const sleep = Math.min(stats.avgSleep / 8, 1) * 10;
  return Math.round(workout + nutrition + steps + water + sleep);
}

export function todayISO(): string {
  return new Date().toISOString().split("T")[0];
}

export function isoToLabel(iso: string): string {
  const d = new Date(iso + "T12:00:00");
  return d.toLocaleDateString("es-ES", { weekday: "short", day: "numeric", month: "short" });
}

