  { icon: "⚖️", label: "Peso actual", value: "80.2 kg", delta: "-2.2 kg", positive: true },
  { icon: "📏", label: "IMC", value: "24.1", delta: "-0.8", positive: true },
  { icon: "🏋️", label: "Entrenos/semana", value: "3.8", delta: "+0.6", positive: true },
