      <GlassCard className="p-4">
        <div className="text-[13px] font-semibold">Registrar pesaje de hoy</div>
        <div className="mt-3 flex gap-2">
          <input
            value={value}
            onChange={(e) => setValue(e.target.value)}
            type="number"
            inputMode="decimal"
