"use client";

import { useState } from "react";
import { motion } from "framer-motion";
import { useTitanStore, xpToLevel, type Friend } from "@/lib/store";
import { useRequireOnboarding } from "@/lib/useRequireOnboarding";
import { ScreenHeader } from "@/components/ScreenHeader";
import { TabBar } from "@/components/TabBar";
import { GlassCard } from "@/components/ui/GlassCard";

type Tab = "ranking" | "amigos" | "duelos";

function Medal({ pos }: { pos: number }) {
  if (pos === 1) return <span className="text-[18px]">🥇</span>;
  if (pos === 2) return <span className="text-[18px]">🥈</span>;
  if (pos === 3) return <span className="text-[18px]">🥉</span>;
  return (
    <div className="flex h-7 w-7 items-center justify-center rounded-full border border-border text-[12px] font-bold text-text-dim">
      {pos}
    </div>
  );
}

export default function RankingPage() {
  const ready = useRequireOnboarding();
  const [tab, setTab] = useState<Tab>("ranking");
  const [newFriendName, setNewFriendName] = useState("");
  const {
    friends, friendRequests, sendFriendRequest, acceptFriendRequest, removeFriend,
    feed, xp, streak, profile, userCommitmentIndex,
  } = useTitanStore();
  const { level } = xpToLevel(xp);
  const firstName = profile.name?.split(" ")[0] ?? "Tú";

  if (!ready) return null;

  const acceptedFriends = friends.filter((f) => f.status === "accepted");
  const pendingReceived = friendRequests.filter((r) => r.status === "pending_received");

  // Build ranking: user + accepted friends
  const meRow = {
    id: "me", name: `${firstName} (tú)`,
    level, commitmentIndex: userCommitmentIndex,
    streak, position: 0, isMe: true,
  };

  const rankRows = [
    meRow,
    ...acceptedFriends.map((f) => ({ ...f, isMe: false })),
  ]
    .sort((a, b) => b.commitmentIndex - a.commitmentIndex)
    .map((r, i) => ({ ...r, position: i + 1 }));

  const tabs: { id: Tab; label: string; icon: string }[] = [
    { id: "ranking", label: "Ranking", icon: "📊" },
    { id: "amigos", label: "Amigos", icon: "👥" },
    { id: "duelos", label: "Duelos", icon: "⚔️" },
  ];

  function handleAddFriend() {
    const name = newFriendName.trim();
    if (!name) return;
    sendFriendRequest(name);
    setNewFriendName("");
  }

  function handleRemove(friend: Friend) {
    if (confirm(`¿Eliminar a ${friend.name} de tus amigos?`)) {
      removeFriend(friend.id);
    }
  }

  return (
    <div className="flex min-h-dvh flex-col gap-4 px-4 pb-[100px]">
      <ScreenHeader title="Social" subtitle="Amigos, ranking y duelos" back="/home" />

      {/* Tabs */}
      <div className="flex gap-2">
        {tabs.map((t) => (
          <button key={t.id} onClick={() => setTab(t.id)}
            className={`flex-1 rounded-full py-2.5 text-[12px] font-bold transition-all ${
              tab === t.id ? "bg-accent text-black" : "border border-border bg-glass text-text-dim"
            }`}>
            {t.icon} {t.label}
          </button>
        ))}
      </div>

      {/* RANKING */}
      {tab === "ranking" && (
        <>
          {acceptedFriends.length === 0 ? (
            <GlassCard className="p-6 text-center">
              <div className="text-[32px] mb-3">👥</div>
              <div className="text-[15px] font-bold">Sin amigos todavía</div>
              <div className="text-[12px] text-text-dim mt-1 leading-relaxed">
                El ranking solo existe entre amigos reales.
                Invita a alguien para competir juntos.
              </div>
              <button
                onClick={() => setTab("amigos")}
                className="mt-4 rounded-full bg-accent px-5 py-2.5 text-[12px] font-bold text-black"
              >
                Añadir amigos
              </button>
            </GlassCard>
          ) : (
            <>
              <GlassCard className="p-4">
                <div className="text-[11px] font-bold text-text-dim mb-2">Índice de compromiso</div>
                <div className="grid grid-cols-5 gap-1.5">
                  {[
                    { label: "Entrenos", pct: 40, color: "bg-accent" },
                    { label: "Nutrición", pct: 25, color: "bg-blue" },
                    { label: "Pasos", pct: 15, color: "bg-success" },
                    { label: "Hidrat.", pct: 10, color: "bg-orange" },
                    { label: "Sueño", pct: 10, color: "bg-purple" },
                  ].map((item) => (
                    <div key={item.label} className="text-center">
                      <div className="text-[11px] font-bold">{item.pct}%</div>
                      <div className={`mt-1 h-1.5 w-full rounded-full ${item.color} opacity-80`} />
                      <div className="mt-1 text-[9px] text-text-dimmer">{item.label}</div>
                    </div>
                  ))}
                </div>
              </GlassCard>

              <div className="flex flex-col gap-2">
                {rankRows.map((row, i) => (
                  <motion.div key={row.id}
                    initial={{ opacity: 0, x: -12 }} animate={{ opacity: 1, x: 0 }}
                    transition={{ delay: i * 0.04 }}>
                    <GlassCard className={`p-3.5 ${row.isMe ? "border-accent/50 bg-accent-dim" : ""}`}>
                      <div className="flex items-center gap-3">
                        <Medal pos={row.position} />
                        <div className="flex h-8 w-8 shrink-0 items-center justify-center rounded-full border border-border-strong bg-glass text-[12px] font-bold">
                          {row.name[0]}
                        </div>
                        <div className="min-w-0 flex-1">
                          <div className={`text-[14px] font-semibold ${row.isMe ? "text-accent" : ""}`}>
                            {row.name}
                          </div>
                          <div className="text-[11px] text-text-dim">
                            Nv. {row.level} · 🔥 {row.streak} días
                          </div>
                        </div>
                        <div className="shrink-0 text-right">
                          <div className="text-[15px] font-extrabold">{row.commitmentIndex}%</div>
                        </div>
                      </div>
                      <div className="mt-2.5 h-1 overflow-hidden rounded-full bg-white/8">
                        <div className={`h-full rounded-full transition-all duration-700 ${row.isMe ? "bg-accent" : "bg-white/30"}`}
                          style={{ width: `${row.commitmentIndex}%` }} />
                      </div>
                    </GlassCard>
                  </motion.div>
                ))}
              </div>
            </>
          )}
        </>
      )}

      {/* AMIGOS */}
      {tab === "amigos" && (
        <div className="flex flex-col gap-3">
          {/* Solicitudes recibidas */}
          {pendingReceived.length > 0 && (
            <div>
              <div className="mb-2 px-1 text-[12px] font-bold text-warning">
                Solicitudes pendientes ({pendingReceived.length})
              </div>
              {pendingReceived.map((req) => (
                <GlassCard key={req.id} className="flex items-center gap-3 p-3.5 mb-2">
                  <div className="flex h-9 w-9 shrink-0 items-center justify-center rounded-full border border-border bg-glass text-[13px] font-bold">
                    {req.name[0]}
                  </div>
                  <div className="flex-1 min-w-0">
                    <div className="text-[14px] font-semibold">{req.name}</div>
                  </div>
                  <button onClick={() => acceptFriendRequest(req.id)}
                    className="rounded-full bg-accent px-3 py-1.5 text-[11px] font-bold text-black">
                    Aceptar
                  </button>
                </GlassCard>
              ))}
            </div>
          )}

          {/* Enviar solicitud */}
          <div className="flex gap-2">
            <input
              value={newFriendName}
              onChange={(e) => setNewFriendName(e.target.value)}
              onKeyDown={(e) => e.key === "Enter" && handleAddFriend()}
              placeholder="Nombre de usuario..."
              className="flex-1 rounded-full border border-border bg-glass px-5 py-3 text-[14px] text-text placeholder:text-text-dimmer outline-none focus:border-accent"
            />
            <button
              onClick={handleAddFriend}
              disabled={!newFriendName.trim()}
              className="rounded-full bg-accent px-4 py-3 text-[13px] font-bold text-black disabled:opacity-40"
            >
              Enviar
            </button>
          </div>

          {/* Amigos aceptados */}
          {acceptedFriends.length === 0 ? (
            <GlassCard className="p-5 text-center">
              <div className="text-[28px] mb-2">🤝</div>
              <div className="text-[13px] font-semibold">Sin amigos todavía</div>
              <div className="text-[11.5px] text-text-dim mt-1">
                Escribe el nombre de un amigo para enviarle una solicitud
              </div>
            </GlassCard>
          ) : (
            acceptedFriends.map((f) => (
              <motion.div key={f.id} initial={{ opacity: 0, x: -8 }} animate={{ opacity: 1, x: 0 }}>
                <GlassCard className="flex items-center gap-3 p-3.5">
                  <div className="flex h-10 w-10 shrink-0 items-center justify-center rounded-full border border-border bg-glass text-[14px] font-bold">
                    {f.name[0]}
                  </div>
                  <div className="min-w-0 flex-1">
                    <div className="text-[14px] font-semibold">{f.name}</div>
                    <div className="text-[11px] text-text-dim">
                      Nv. {f.level} · 🔥 {f.streak} días · {f.commitmentIndex}% índice
                    </div>
                  </div>
                  <button
                    onClick={() => handleRemove(f)}
                    className="rounded-full border border-border-strong px-3 py-1.5 text-[11px] font-semibold text-text-dim"
                  >
                    Eliminar
                  </button>
                </GlassCard>
              </motion.div>
            ))
          )}

          {/* Feed */}
          {feed.length > 0 && (
            <div>
              <div className="mb-2 px-1 text-[12px] font-bold text-text-dim">Actividad reciente</div>
              {feed.map((item, i) => (
                <motion.div key={item.id} initial={{ opacity: 0, y: 8 }} animate={{ opacity: 1, y: 0 }}
                  transition={{ delay: i * 0.05 }} className="mb-2">
                  <GlassCard className="flex items-start gap-3 p-3.5">
                    <div className="flex h-9 w-9 shrink-0 items-center justify-center rounded-full border border-border bg-glass text-sm font-bold">
                      {item.userName[0]}
                    </div>
                    <div className="min-w-0 flex-1">
                      <div className="text-[13.5px]">
                        <span className="font-semibold">{item.userName}</span>{" "}
                        <span className="text-text-dim">{item.action}</span>
                      </div>
                      <div className="mt-0.5 text-[11px] text-text-dimmer">{item.timestamp}</div>
                    </div>
                  </GlassCard>
                </motion.div>
              ))}
            </div>
          )}
        </div>
      )}

      {/* DUELOS */}
      {tab === "duelos" && (
        <div className="flex flex-col gap-3">
          <GlassCard className="p-4">
            <div className="text-[13px] font-bold">⚔️ Duelos de fin de semana</div>
            <div className="mt-1 text-[12px] text-text-dim leading-relaxed">
              Los duelos se crean automáticamente cada sábado. Gana quien acumule más pasos, actividad o puntos — los datos vienen exclusivamente de tu reloj inteligente.
            </div>
          </GlassCard>

          {acceptedFriends.length === 0 ? (
            <GlassCard className="p-5 text-center">
              <div className="text-[28px] mb-2">👥</div>
              <div className="text-[12px] text-text-dim">Necesitas al menos un amigo para lanzar un duelo</div>
              <button onClick={() => setTab("amigos")}
                className="mt-3 rounded-full border border-border-strong px-4 py-2 text-[12px] font-semibold">
                Añadir amigos
              </button>
            </GlassCard>
          ) : (
            <GlassCard className="flex flex-col items-center gap-2 p-5 text-center">
              <div className="text-[32px]">🏆</div>
              <div className="text-[14px] font-bold">Duelo disponible el sábado</div>
              <div className="text-[12px] text-text-dim">Vuelve el fin de semana para lanzar un duelo</div>
              <button disabled
                className="mt-2 rounded-full bg-accent/40 px-6 py-3 text-[13px] font-bold text-black/60 cursor-not-allowed">
                Disponible el sábado
              </button>
            </GlassCard>
          )}
        </div>
      )}

      <TabBar />
    </div>
  );
}

"use client";

import { useState } from "react";
import { motion } from "framer-motion";
import { useTitanStore, type Challenge, type ChallengeType } from "@/lib/store";
import { useRequireOnboarding } from "@/lib/useRequireOnboarding";
import { ScreenHeader } from "@/components/ScreenHeader";
import { TabBar } from "@/components/TabBar";
import { GlassCard } from "@/components/ui/GlassCard";

const TYPE_LABELS: Record<ChallengeType, string> = {
  daily: "Diario", weekly: "Semanal", monthly: "Mensual",
};
const TYPE_COLORS: Record<ChallengeType, string> = {
  daily: "text-success", weekly: "text-blue", monthly: "text-purple",
};
const TYPE_BG: Record<ChallengeType, string> = {
  daily: "bg-success-dim border-success/30",
  weekly: "bg-blue-dim border-blue/30",
  monthly: "bg-purple-dim border-purple/30",
};

export default function RetosPage() {
  const ready = useRequireOnboarding();
  const challenges = useTitanStore((s) => s.challenges);
  const healthSource = useTitanStore((s) => s.healthSource);
  const [filter, setFilter] = useState<ChallengeType | "all">("all");

  if (!ready) return null;

  const watchConnected = healthSource !== "none";

  const filtered: Challenge[] =
    filter === "all" ? challenges : challenges.filter((c: Challenge) => c.type === filter);

  const totalXp = challenges
    .filter((c: Challenge) => c.completed)
    .reduce((sum, c: Challenge) => sum + c.xpReward, 0);
  const completedCount = challenges.filter((c: Challenge) => c.completed).length;

  return (
    <div className="flex min-h-dvh flex-col gap-4 px-4 pb-[100px]">
      <ScreenHeader title="Retos" subtitle={`${completedCount}/${challenges.length} completados · +${totalXp} XP`} back="/home" />

      {/* Reloj requerido */}
      {!watchConnected && (
        <GlassCard className="p-4 border-warning/30 bg-warning-dim">
          <div className="flex items-start gap-3">
            <span className="text-[22px]">⌚</span>
            <div>
              <div className="text-[13px] font-bold text-warning">Reloj inteligente requerido</div>
              <div className="text-[11.5px] text-text-dim mt-0.5 leading-relaxed">
                Los retos marcados con ⌚ solo pueden confirmarse con datos reales del reloj. Conecta Apple Health o Health Connect desde tu perfil.
              </div>
            </div>
          </div>
        </GlassCard>
      )}

      {/* Resumen */}
      <div className="flex gap-2.5">
        {(["daily", "weekly", "monthly"] as ChallengeType[]).map((type) => {
          const group = challenges.filter((c: Challenge) => c.type === type);
          const done = group.filter((c: Challenge) => c.completed).length;
          return (
            <div key={type} className={`flex-1 rounded-[18px] border p-3.5 ${TYPE_BG[type]}`}>
              <div className={`text-[20px] font-extrabold tabular-nums ${TYPE_COLORS[type]}`}>
                {done}/{group.length}
              </div>
              <div className="mt-0.5 text-[10px] font-bold text-text-dim">
                {TYPE_LABELS[type]}s
              </div>
            </div>
          );
        })}
      </div>

      {/* Filtros */}
      <div className="flex gap-2">
        {(["all", "daily", "weekly", "monthly"] as (ChallengeType | "all")[]).map((f) => (
          <button key={f} onClick={() => setFilter(f)}
            className={`rounded-full px-4 py-2 text-[12px] font-bold transition-all ${
              filter === f ? "bg-accent text-black" : "border border-border bg-glass text-text-dim"
            }`}>
            {f === "all" ? "Todos" : TYPE_LABELS[f as ChallengeType] + "s"}
          </button>
        ))}
      </div>

      {/* Lista */}
      <div className="flex flex-col gap-3">
        {filtered.map((challenge: Challenge, i: number) => {
          const pct = Math.min(Math.round((challenge.progress / challenge.target) * 100), 100);
          const blocked = challenge.requiresWatch && !watchConnected;
          return (
            <motion.div key={challenge.id}
              initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }}
              transition={{ delay: i * 0.04 }}>
              <GlassCard className={`p-4 ${
                challenge.completed ? "border-accent/30 bg-accent-dim" :
                blocked ? "opacity-60" : ""
              }`}>
                <div className="flex items-start justify-between gap-3">
                  <div className="min-w-0 flex-1">
                    <div className="flex items-center gap-2 flex-wrap">
                      <span className={`text-[10px] font-bold uppercase tracking-wide px-2 py-0.5 rounded-full border ${TYPE_BG[challenge.type as ChallengeType]} ${TYPE_COLORS[challenge.type as ChallengeType]}`}>
                        {TYPE_LABELS[challenge.type as ChallengeType]}
                      </span>
                      {challenge.requiresWatch && (
                        <span className={`text-[10px] font-bold px-2 py-0.5 rounded-full border ${
                          watchConnected ? "border-success/30 bg-success-dim text-success" : "border-warning/30 bg-warning-dim text-warning"
                        }`}>
                          ⌚ {watchConnected ? "Sincronizado" : "Requiere reloj"}
                        </span>
                      )}
                      {challenge.completed && (
                        <span className="text-[10px] font-bold text-accent">✓ Completado</span>
                      )}
                    </div>
                    <div className="mt-1.5 text-[15px] font-bold">{challenge.title}</div>
                    <div className="mt-0.5 text-[12px] text-text-dim">{challenge.description}</div>
                  </div>
                  <div className="shrink-0 text-right">
                    <div className="text-[14px] font-extrabold text-accent">+{challenge.xpReward}</div>
                    <div className="text-[10px] text-text-dimmer">XP</div>
                  </div>
                </div>

                <div className="mt-3">
                  <div className="mb-1 flex items-center justify-between">
                    <span className="text-[11px] text-text-dim">
                      {blocked
                        ? "Conecta el reloj para ver el progreso"
                        : `${challenge.progress.toLocaleString("es")} / ${challenge.target.toLocaleString("es")} ${challenge.unit}`}
                    </span>
                    {!blocked && <span className="text-[11px] font-bold">{pct}%</span>}
                  </div>
                  <div className="h-2 overflow-hidden rounded-full bg-white/10">
                    <motion.div
                      className={`h-full rounded-full ${challenge.completed ? "bg-accent" : blocked ? "bg-white/20" : "bg-white/40"}`}
                      initial={{ width: 0 }}
                      animate={{ width: blocked ? "0%" : `${pct}%` }}
                      transition={{ duration: 0.8, ease: "easeOut" }}
                    />
                  </div>
                </div>
              </GlassCard>
            </motion.div>
          );
        })}
      </div>

      <TabBar />
    </div>
  );
}

"use client";

import { useState } from "react";
import { motion } from "framer-motion";
import { useTitanStore } from "@/lib/store";
import { useRequireOnboarding } from "@/lib/useRequireOnboarding";
import { ScreenHeader } from "@/components/ScreenHeader";
import { TabBar } from "@/components/TabBar";
import { GlassCard } from "@/components/ui/GlassCard";

const CATEGORIES = [
  "🥩 Proteínas",
  "🥦 Verduras",
  "🥣 Cereales",
  "🥛 Lácteos / Huevos",
  "🧂 Despensa",
  "🍎 Frutas",
  "🥫 Otros",
];

export default function CompraPage() {
  const ready = useRequireOnboarding();
  const shoppingList = useTitanStore((s) => s.shoppingList);
  const addShoppingItem = useTitanStore((s) => s.addShoppingItem);
  const removeShoppingItem = useTitanStore((s) => s.removeShoppingItem);
  const toggleShoppingItem = useTitanStore((s) => s.toggleShoppingItem);
  const resetShoppingList = useTitanStore((s) => s.resetShoppingList);
  const generateShoppingListFromMenu = useTitanStore((s) => s.generateShoppingListFromMenu);
  const profile = useTitanStore((s) => s.profile);

  const [newName, setNewName] = useState("");
  const [newCategory, setNewCategory] = useState(CATEGORIES[0]);
  const [newQty, setNewQty] = useState("");
  const [showAdd, setShowAdd] = useState(false);
  const [confirmReset, setConfirmReset] = useState(false);

  if (!ready) return null;

  const market = profile.supermarket ?? "tu supermercado";
  const doneCount = shoppingList.filter((i) => i.checked).length;
  const pct = shoppingList.length > 0
    ? Math.round((doneCount / shoppingList.length) * 100)
    : 0;

  // Group by category
  const grouped: Record<string, typeof shoppingList> = {};
  shoppingList.forEach((item) => {
    grouped[item.category] = grouped[item.category] ?? [];
    grouped[item.category].push(item);
  });

  function handleAdd() {
    const name = newName.trim();
    if (!name) return;
    addShoppingItem({ name, category: newCategory, quantity: newQty.trim() || undefined });
    setNewName("");
    setNewQty("");
    setShowAdd(false);
  }

  return (
    <div className="flex min-h-dvh flex-col gap-4 px-4 pb-[100px]">
      <ScreenHeader title="Lista de la compra" subtitle={market} back="/home" />

      {/* Progress bar */}
      {shoppingList.length > 0 && (
        <div className="sticky top-0 z-10 -mx-4 bg-bg/90 px-4 pb-3 pt-1 backdrop-blur-md">
          <div className="flex items-center justify-between text-[12px] font-semibold text-text-dim">
            <span>{doneCount}/{shoppingList.length} artículos · {pct}%</span>
            <button
              onClick={() => setConfirmReset(true)}
              className="text-text-dimmer underline underline-offset-2"
            >
              Reiniciar
            </button>
          </div>
          <div className="mt-1.5 h-[5px] overflow-hidden rounded-full bg-white/8">
            <div className="h-full rounded-full bg-accent transition-all duration-500"
              style={{ width: `${pct}%` }} />
          </div>
        </div>
      )}

      {/* Confirmación reinicio */}
      {confirmReset && (
        <GlassCard className="p-4 border-danger/30 bg-danger-dim">
          <div className="text-[13px] font-bold text-danger mb-2">¿Reiniciar lista?</div>
          <div className="text-[12px] text-text-dim mb-3">Se desmarcará todo pero no se eliminará ningún artículo.</div>
          <div className="flex gap-2">
            <button onClick={() => { resetShoppingList(); setConfirmReset(false); }}
              className="rounded-full bg-danger px-4 py-2 text-[12px] font-bold text-white">
              Reiniciar
            </button>
            <button onClick={() => setConfirmReset(false)}
              className="rounded-full border border-border px-4 py-2 text-[12px] font-semibold">
              Cancelar
            </button>
          </div>
        </GlassCard>
      )}

      {/* Acciones */}
      <div className="flex gap-2">
        <button
          onClick={() => setShowAdd((s) => !s)}
          className="flex-1 rounded-full border border-border bg-glass py-2.5 text-[12px] font-semibold"
        >
          + Añadir artículo
        </button>
        <button
          onClick={generateShoppingListFromMenu}
          className="flex-1 rounded-full bg-accent py-2.5 text-[12px] font-bold text-black"
        >
          🤖 Del menú
        </button>
      </div>

      {/* Formulario añadir */}
      {showAdd && (
        <motion.div initial={{ opacity: 0, height: 0 }} animate={{ opacity: 1, height: "auto" }}>
          <GlassCard className="p-4 flex flex-col gap-3">
            <input
              value={newName}
              onChange={(e) => setNewName(e.target.value)}
              onKeyDown={(e) => e.key === "Enter" && handleAdd()}
              placeholder="Nombre del artículo..."
              autoFocus
              className="w-full rounded-[10px] border border-border bg-glass px-3.5 py-2.5 text-[14px] outline-none focus:border-accent"
            />
            <div className="flex gap-2">
              <input
                value={newQty}
                onChange={(e) => setNewQty(e.target.value)}
                placeholder="Cantidad (ej. 500g)"
                className="flex-1 rounded-[10px] border border-border bg-glass px-3.5 py-2.5 text-[14px] outline-none focus:border-accent"
              />
              <select
                value={newCategory}
                onChange={(e) => setNewCategory(e.target.value)}
                className="flex-1 rounded-[10px] border border-border bg-glass px-3 py-2.5 text-[13px] outline-none focus:border-accent"
              >
                {CATEGORIES.map((c) => (
                  <option key={c} value={c}>{c}</option>
                ))}
              </select>
            </div>
            <button
              onClick={handleAdd}
              disabled={!newName.trim()}
              className="w-full rounded-full bg-accent py-2.5 text-[13px] font-bold text-black disabled:opacity-40"
            >
              Añadir
            </button>
          </GlassCard>
        </motion.div>
      )}

      {/* Lista vacía */}
      {shoppingList.length === 0 && (
        <GlassCard className="p-6 text-center">
          <div className="text-[32px] mb-2">🛒</div>
          <div className="text-[15px] font-bold">Lista vacía</div>
          <div className="text-[12px] text-text-dim mt-1 leading-relaxed">
            Añade artículos manualmente o genera la lista automáticamente desde tu menú semanal.
          </div>
        </GlassCard>
      )}

      {/* Completada */}
      {shoppingList.length > 0 && doneCount === shoppingList.length && (
        <div className="rounded-[20px] border border-accent bg-accent-dim p-4 text-center text-[13.5px] font-semibold text-accent">
          🛒 ¡Compra completada!
        </div>
      )}

      {/* Grupos */}
      <div className="flex flex-col gap-5">
        {Object.entries(grouped).map(([category, items]) => (
          <div key={category}>
            <div className="mb-2 px-1 flex items-center justify-between">
              <span className="text-[12px] font-bold text-text-dim">{category}</span>
              <span className="text-[11px] text-text-dimmer">
                {items.filter((i) => i.checked).length}/{items.length}
              </span>
            </div>
            <div className="flex flex-col gap-2">
              {items.map((item) => (
                <div key={item.id} className="flex items-center gap-2">
                  <button
                    onClick={() => toggleShoppingItem(item.id)}
                    className="flex flex-1 items-center gap-3 rounded-[14px] border border-border bg-glass px-4 py-3.5 text-left transition-all active:scale-[0.98]"
                  >
                    <span className={`flex h-6 w-6 shrink-0 items-center justify-center rounded-[7px] border text-[13px] font-bold transition-all ${
                      item.checked ? "border-accent bg-accent text-black" : "border-border-strong text-transparent"
                    }`}>✓</span>
                    <span className={`flex-1 text-[14px] transition-all ${
                      item.checked ? "text-text-dimmer line-through" : "text-text"
                    }`}>
                      {item.name}
                    </span>
                    {item.quantity && (
                      <span className="text-[11px] text-text-dimmer shrink-0">{item.quantity}</span>
                    )}
                  </button>
                  <button
                    onClick={() => removeShoppingItem(item.id)}
                    className="flex h-10 w-10 shrink-0 items-center justify-center rounded-[14px] border border-border bg-glass text-[14px] text-text-dim transition-all active:bg-danger-dim active:text-danger"
                  >
                    ×
                  </button>
                </div>
              ))}
            </div>
          </div>
        ))}
      </div>

      <TabBar />
    </div>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { useTitanStore } from "@/lib/store";
import { useRequireOnboarding } from "@/lib/useRequireOnboarding";
import { TitanAvatar } from "@/components/ui/TitanAvatar";
import { TabBar } from "@/components/TabBar";

const QUICK_PROMPTS = [
  "¿Cómo voy hoy?",
  "Receta alta en proteína",
  "Estoy cansado",
  "¿Cuánta proteína me falta?",
  "Motívame",
  "¿Qué como ahora?",
];

export default function TitanChatPage() {
  const ready = useRequireOnboarding();
  const chatMessages = useTitanStore((s) => s.chatMessages);
  const sendChatMessage = useTitanStore((s) => s.sendChatMessage);
  const chatLoading = useTitanStore((s) => s.chatLoading);
  const [text, setText] = useState("");
  const bodyRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    bodyRef.current?.scrollTo({ top: bodyRef.current.scrollHeight, behavior: "smooth" });
  }, [chatMessages, chatLoading]);

  function submit(e: React.FormEvent) {
    e.preventDefault();
    if (!text.trim() || chatLoading) return;
    sendChatMessage(text.trim());
    setText("");
  }

  if (!ready) return null;

  return (
    <div className="flex h-dvh flex-col">
      {/* Header */}
      <div className="flex shrink-0 items-center gap-3 border-b border-border px-5 pb-3.5 pt-5">
        <TitanAvatar size={38} pulse />
        <div>
          <div className="text-[15px] font-bold">Titan</div>
          <div className="text-[11.5px] text-text-dim">Entrenador personal · IA</div>
        </div>
        <div className="ml-auto flex items-center gap-1.5 rounded-full border border-success/30 bg-success-dim px-3 py-1">
          <div className="h-1.5 w-1.5 rounded-full bg-success" />
          <span className="text-[11px] font-semibold text-success">Activo</span>
        </div>
      </div>

      {/* Mensajes */}
      <div ref={bodyRef} className="flex flex-1 flex-col gap-3 overflow-y-auto px-5 py-4">
        {chatMessages.length === 0 && (
          <div className="flex flex-col items-center gap-3 pt-8 text-center">
            <TitanAvatar size={56} />
            <div className="text-[15px] font-bold">¡Hola! Soy Titan</div>
            <div className="text-[13px] text-text-dim max-w-[260px] leading-relaxed">
              Tu entrenador con IA. Pregúntame sobre nutrición, entrenamiento, hábitos, recetas o tu progreso.
            </div>
          </div>
        )}

        <AnimatePresence initial={false}>
          {chatMessages.map((m, i) =>
            m.role === "user" ? (
              <motion.div key={i}
                initial={{ opacity: 0, x: 20 }} animate={{ opacity: 1, x: 0 }}
                className="max-w-[80%] self-end rounded-[18px] rounded-tr-[4px] bg-accent px-4 py-3 text-[13.5px] font-semibold text-black">
                {m.text}
              </motion.div>
            ) : (
              <motion.div key={i}
                initial={{ opacity: 0, x: -20 }} animate={{ opacity: 1, x: 0 }}
                className="flex max-w-[88%] items-start gap-2.5">
                <TitanAvatar size={28} />
                <div className="rounded-[18px] rounded-tl-[4px] border border-border bg-glass-strong px-4 py-[13px] text-[14px] leading-[1.55]">
                  {m.text.split("\n").map((line, j) => (
                    <p key={j} className={j > 0 ? "mt-2" : ""}>{line}</p>
                  ))}
                </div>
              </motion.div>
            )
          )}

          {/* Typing indicator */}
          {chatLoading && (
            <motion.div key="loading"
              initial={{ opacity: 0, x: -20 }} animate={{ opacity: 1, x: 0 }}
              exit={{ opacity: 0 }}
              className="flex max-w-[88%] items-start gap-2.5">
              <TitanAvatar size={28} />
              <div className="rounded-[18px] rounded-tl-[4px] border border-border bg-glass-strong px-4 py-[13px]">
                <div className="flex gap-1 items-center">
                  {[0, 1, 2].map((dot) => (
                    <div key={dot}
                      className="h-2 w-2 rounded-full bg-accent/60"
                      style={{ animation: `bounce 1.2s ease infinite ${dot * 0.2}s` }}
                    />
                  ))}
                </div>
              </div>
            </motion.div>
          )}
        </AnimatePresence>
      </div>

      {/* Quick prompts */}
      <div className="shrink-0 flex gap-2 overflow-x-auto px-5 pb-2 pt-1 [scrollbar-width:none]">
        {QUICK_PROMPTS.map((p) => (
          <button key={p}
            onClick={() => { if (!chatLoading) sendChatMessage(p); }}
            disabled={chatLoading}
            className="shrink-0 rounded-full border border-border bg-glass px-3.5 py-2 text-[12px] font-semibold text-text-dim whitespace-nowrap disabled:opacity-40">
            {p}
          </button>
        ))}
      </div>

      {/* Input */}
      <form className="shrink-0 px-5 pb-[100px] pt-2" onSubmit={submit}>
        <div className="flex items-center gap-2.5 rounded-full border border-border bg-glass py-1.5 pl-[18px] pr-1.5">
          <input
            value={text}
            onChange={(e) => setText(e.target.value)}
            placeholder="Pregúntale a Titan..."
            disabled={chatLoading}
            className="flex-1 bg-transparent py-2 text-[14px] text-text placeholder:text-text-dimmer outline-none disabled:opacity-60"
          />
          <button
            type="submit"
            disabled={!text.trim() || chatLoading}
            className="flex h-9 w-9 shrink-0 items-center justify-center rounded-full bg-accent text-[15px] font-extrabold text-black disabled:opacity-40"
          >
            ↑
          </button>
        </div>
      </form>

      <TabBar />

      <style>{`
        @keyframes bounce {
          0%, 80%, 100% { transform: scale(0.8); opacity: 0.5; }
          40% { transform: scale(1); opacity: 1; }
        }
      `}</style>
    </div>
  );
}

"use client";

import { useState } from "react";
import { motion } from "framer-motion";
import { useTitanStore, xpToLevel, type Friend } from "@/lib/store";
import { useRequireOnboarding } from "@/lib/useRequireOnboarding";
import { ScreenHeader } from "@/components/ScreenHeader";
import { TabBar } from "@/components/TabBar";
import { GlassCard } from "@/components/ui/GlassCard";

type Tab = "ranking" | "amigos" | "duelos";

