  weighIns: WeighIn[];
  addWeighIn: (weight: number) => void;

  // ── Fotos de progreso ──
  progressPhotos: ProgressPhoto[];
  addProgressPhoto: (dataUrl: string, note?: string) => void;
  removeProgressPhoto: (id: string) => void;

