                  <motion.div
                    key={row.id}
                    initial={{ opacity: 0, x: -12 }}
                    animate={{ opacity: 1, x: 0 }}
                    transition={{ delay: i * 0.04 }}
                  >
                    <GlassCard
                      className={`p-3.5 ${row.isMe ? "border-accent/50 bg-accent-dim" : ""}`}
                    >
                      <div className="flex items-center gap-3">
                        <Medal pos={row.position} />
