              Enviar
            </button>
          </div>

          {/* Lista amigos */}
          {acceptedFriends.length === 0 ? (
            <GlassCard className="p-5 text-center">
              <div className="text-[28px] mb-2">🤝</div>
              <div className="text-[13px] font-semibold">Sin amigos todavía</div>
